+    price: "$78",
+    rating: "4.9",
+    badge: "Best seller",
+    image: "https://images.unsplash.com/photo-1602810318383-e386cc2a3ccf?auto=format&fit=crop&w=700&q=80",
+    alt: "Man wearing a relaxed blue oxford shirt"
+  }
+];
+
+const productGrid = document.querySelector("#product-grid");
+const cartCount = document.querySelector("#cart-count");
+const navToggle = document.querySelector(".nav-toggle");
+const navLinks = document.querySelector("#primary-menu");
+const signupForm = document.querySelector("#signup-form");
+const formMessage = document.querySelector("#form-message");
+
+let cartItems = 0;
+
+function renderProducts() {
+  productGrid.innerHTML = products.map((product) => `
+    <article class="product-card">
+      <div class="product-image">
+        <img src="${product.image}" alt="${product.alt}">
+        <span class="product-pill">${product.badge}</span>
+      </div>
+      <div class="product-info">
+        <div class="product-meta">
+          <span>${product.category}</span>
+          <span class="rating">★ ${product.rating}</span>
+        </div>
+        <h3>${product.name}</h3>
+        <div class="price-row">
+          <span class="price">${product.price}</span>
+          <button class="add-button" type="button" data-product="${product.name}">Add</button>
+        </div>
+      </div>
+    </article>
+  `).join("");
+}
+
+function updateCountdown() {
+  const now = new Date();
+  const dealEnd = new Date(now);
+  dealEnd.setDate(now.getDate() + 5);
+  dealEnd.setHours(23, 59, 59, 999);
+
+  const remaining = dealEnd - now;
+  const days = Math.floor(remaining / (1000 * 60 * 60 * 24));
+  const hours = Math.floor((remaining / (1000 * 60 * 60)) % 24);
+  const minutes = Math.floor((remaining / (1000 * 60)) % 60);
+
+  document.querySelector("#days").textContent = String(days).padStart(2, "0");
+  document.querySelector("#hours").textContent = String(hours).padStart(2, "0");
+  document.querySelector("#minutes").textContent = String(minutes).padStart(2, "0");
+}
+
+function handleProductClick(event) {
+  const button = event.target.closest(".add-button");
+
+  if (!button) {
+    return;
+  }
+
+  cartItems += 1;
+  cartCount.textContent = cartItems;
+  button.textContent = "Added";
+  setTimeout(() => {
+    button.textContent = "Add";
+  }, 1000);
+}
+
+function handleMenuToggle() {
+  const isOpen = navLinks.classList.toggle("is-open");
+  navToggle.setAttribute("aria-expanded", String(isOpen));
+}
+
+function handleSignup(event) {
+  event.preventDefault();
+  const email = new FormData(signupForm).get("email") || document.querySelector("#email").value;
+
+  formMessage.textContent = `Thanks, ${email}. Your member invite is on the way.`;
+  signupForm.reset();
+}
+
+renderProducts();
+updateCountdown();
+setInterval(updateCountdown, 60 * 1000);
+
+productGrid.addEventListener("click", handleProductClick);
+navToggle.addEventListener("click", handleMenuToggle);
+signupForm.addEventListener("submit", handleSignup);
